public class CacheAsideRepository {
    private final Cache<String, User> cache;
    private final UserRepository database;

    public CacheAsideRepository(Cache<String, User> cache, UserRepository database) {
        this.cache = cache;
        this.database = database;
    }

    public User findById(String userId) {
        User user = cache.getIfPresent(userId);
        if (user != null) {
            return user;
        }
        user = database.findById(userId);
        if (user != null) {
            cache.put(userId, user);
        }
        return user;
    }

    public void update(User user) {
        database.save(user);
        cache.invalidate(user.getId());
    }
}
